import{_ as o,c as i,o as e,ae as r}from"./chunks/framework.BQlYxExx.js";const k=JSON.parse('{"title":"Opis projektu, grupa, podział ról","description":"","frontmatter":{},"headers":[],"relativePath":"opis-projektu.md","filePath":"opis-projektu.md"}'),n={name:"opis-projektu.md"};function t(s,a,l,z,c,p){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="opis-projektu-grupa-podział-rol" tabindex="-1">Opis projektu, grupa, podział ról <a class="header-anchor" href="#opis-projektu-grupa-podział-rol" aria-label="Permalink to &quot;Opis projektu, grupa, podział ról&quot;">​</a></h1><h2 id="_1-1-opis-projektu" tabindex="-1">1.1. Opis projektu <a class="header-anchor" href="#_1-1-opis-projektu" aria-label="Permalink to &quot;1.1. Opis projektu&quot;">​</a></h2><p>Temat projektu: Aplikacja do zbierania ogłoszeń zwierząt do adoptowania ze wszystkich schronisk w Polsce z pomocą inteligentnego agregowania za pomocą scrapera AI opartego na API Gemini.</p><p>Projekt ma za zadanie w intuicyjny i przyjazny sposób umożliwić użytkownikowi przejście przez wszystkie etapy dostosowywania preferencji swojego wymarzonego zwierzaka, przeanalizować je i dopasować odpowiednie ogłoszenia tak, aby można było szybko nawiązać kontakt z danym schroniskiem, aby móc adoptować zwierzaka. Aplikacja powinna zawierać ogłoszenia ze wszystkich możliwych dostępnych internetowo schronisk w Polsce, pomijając social media. Projekt ma na celu również przedstawienie podglądu zwierzaka łącznie z jego pobranymi cechami, zdjęciami oraz innymi cennymi informacjami potrzebnymi w procesie adopcyjnym.</p><h2 id="_1-2-grupa" tabindex="-1">1.2. Grupa <a class="header-anchor" href="#_1-2-grupa" aria-label="Permalink to &quot;1.2. Grupa&quot;">​</a></h2><ul><li>Krzysztof Kozyra</li><li>Tomasz Rebizant</li></ul><h2 id="_1-3-podział-rol" tabindex="-1">1.3. Podział ról <a class="header-anchor" href="#_1-3-podział-rol" aria-label="Permalink to &quot;1.3. Podział ról&quot;">​</a></h2><ul><li>Krzysztof Kozyra - Backend, DevOps, Tester, Project Manager</li><li>Tomasz Rebizant - Frontend, Tester</li></ul><h2 id="_1-4-persony-uzytkownika" tabindex="-1">1.4. Persony Użytkownika <a class="header-anchor" href="#_1-4-persony-uzytkownika" aria-label="Permalink to &quot;1.4. Persony Użytkownika&quot;">​</a></h2><p>Aby lepiej zrozumieć potrzeby i cele użytkowników aplikacji ŁapGo, zdefiniowano kluczowe persony:</p><h3 id="_1-4-1-anna-24-lat-–-poszukiwaczka-kociaka" tabindex="-1">1.4.1. Anna (24 lat) – Poszukiwaczka Kociaka. <a class="header-anchor" href="#_1-4-1-anna-24-lat-–-poszukiwaczka-kociaka" aria-label="Permalink to &quot;1.4.1. Anna (24 lat) – Poszukiwaczka Kociaka.&quot;">​</a></h3><ul><li><strong>Cel</strong>: Znaleźć małego, przyjaznego kociaka pasującego do życia w mieszkaniu w Legnicy.</li><li><strong>Wyzwania</strong>: Czuje się przytłoczona ilością informacji i nie wie, gdzie szukać ogłoszeń, gdyż nie chce przeglądać dziesiątek stron schronisk.</li><li><strong>Kluczowe Funkcje</strong>: Ustawianie precyzyjnych preferencji, wyświetlanie ogłoszeń z pobliskich schronisk, łatwe pośrednictwo w kontakcie.</li></ul><h3 id="_1-4-2-piotr-35-lat-–-doswiadczony-adopter-psa" tabindex="-1">1.4.2. Piotr (35 lat) – Doświadczony Adopter Psa. <a class="header-anchor" href="#_1-4-2-piotr-35-lat-–-doswiadczony-adopter-psa" aria-label="Permalink to &quot;1.4.2. Piotr (35 lat) – Doświadczony Adopter Psa.&quot;">​</a></h3><ul><li><strong>Cel</strong>: Adoptować drugiego dużego psa o konkretnych cechach (np. łagodny, rodzinny) i znaleźć go w promieniu 50 km od Wrocławia.</li><li><strong>Wyzwania</strong>: Potrzebuje szybkiego i zaawansowanego filtrowania, aby wykluczyć zwierzęta, które nie pasują do jego trybu życia lub lokalizacji.</li><li><strong>Kluczowe Funkcje</strong>: Zaawansowane filtrowanie, geolokalizacja i mapa, zapisywanie zwierząt do ulubionych.</li></ul><h3 id="_1-4-3-schronisko-azyl-–-administrator-schroniska" tabindex="-1">1.4.3. Schronisko &quot;Azyl&quot; – Administrator Schroniska. <a class="header-anchor" href="#_1-4-3-schronisko-azyl-–-administrator-schroniska" aria-label="Permalink to &quot;1.4.3. Schronisko &quot;Azyl&quot; – Administrator Schroniska.&quot;">​</a></h3><ul><li><strong>Cel</strong>: Zwiększyć widoczność zwierząt ze schroniska i ułatwić proces adopcyjny poprzez umieszczenie ogłoszeń w centralnej bazie.</li><li><strong>Wyzwania</strong>: Często ogłoszenia są nieaktualne na zintegrowanych platformach; potrzebuje możliwości ręcznego dodawania i zarządzania statusami adopcyjnymi.</li><li><strong>Kluczowe Funkcje</strong>: Możliwość dodawania własnych zwierząt, zmiana statusu adopcyjnego, dostęp do panelu administratora/schroniska.</li></ul>',16)])])}const u=o(n,[["render",t]]);export{k as __pageData,u as default};
